import { registerWebComponents } from '@domg-wc/common';
import { VlButtonComponent, VlTitleComponent } from '@domg-wc/components/atom';
import { VlInputSliderComponent, VlToasterComponent } from '@domg-wc/components/block';
import {
    VlMap,
    VlMapActionControls,
    VlMapBaseLayerGRB,
    VlMapBaseLayerGRBGray,
    VlMapBaseLayerGRBOrtho,
    VlMapDeleteAction,
    VlMapDrawLineAction,
    VlMapDrawPointAction,
    VlMapDrawPolygonAction,
    VlMapFeaturesLayer,
    VlMapLayerCircleStyle,
    VlMapLayerStyle,
    VlMapLayerSwitcher,
    VlMapLegend,
    VlMapMeasureAction,
    VlMapMeasureControl,
    VlMapModifyAction,
    VlMapOverviewMap,
    VlMapSelectAction,
    VlMapSideSheet,
} from '@domg-wc/map';

// De import registreert de elementen; registerWebComponents houdt de klassen in de bundel.
registerWebComponents([
    VlButtonComponent,
    VlTitleComponent,
    VlInputSliderComponent,
    VlToasterComponent,
    VlMap,
    VlMapActionControls,
    VlMapBaseLayerGRB,
    VlMapBaseLayerGRBGray,
    VlMapBaseLayerGRBOrtho,
    VlMapDeleteAction,
    VlMapDrawLineAction,
    VlMapDrawPointAction,
    VlMapDrawPolygonAction,
    VlMapFeaturesLayer,
    VlMapLayerCircleStyle,
    VlMapLayerStyle,
    VlMapLayerSwitcher,
    VlMapLegend,
    VlMapMeasureAction,
    VlMapMeasureControl,
    VlMapModifyAction,
    VlMapOverviewMap,
    VlMapSelectAction,
    VlMapSideSheet,
]);

const map = document.querySelector('#map-playground');
const actionNames = ['draw-point', 'draw-line', 'draw-polygon', 'modify', 'delete'];
const getAction = (name) => map.querySelector(`.${name}-action`);
const getToggleButton = (name) => map.querySelector(`.${name}-toggle-button`);

// De laag Shapes krijgt een punt, een lijn en een polygoon als GeoJSON in Lambert 72 (EPSG:31370). De setter van
// features zet het object als JSON-string in het attribuut features.
map.querySelector('vl-map-features-layer[name="Shapes"]').features = {
    type: 'FeatureCollection',
    features: [
        {
            type: 'Feature',
            id: 1,
            geometry: { type: 'Point', coordinates: [210000, 190000] },
        },
        {
            type: 'Feature',
            id: 2,
            geometry: {
                type: 'LineString',
                coordinates: [
                    [170000, 170000],
                    [150000, 206000],
                ],
            },
        },
        {
            type: 'Feature',
            id: 3,
            geometry: {
                type: 'Polygon',
                coordinates: [
                    [
                        [44000, 171000],
                        [100000, 171000],
                        [100000, 205000],
                        [44000, 205000],
                        [44000, 171000],
                    ],
                ],
            },
        },
    ],
};

// De slider (0 tot 100) zet de opacity (0 tot 1) van elke vl-map-features-layer.
map.querySelector('vl-input-slider').addEventListener('vl-change-value', ({ detail: { value } }) => {
    map.querySelectorAll('vl-map-features-layer').forEach((layer) => {
        layer.setAttribute('opacity', String(value / 100));
    });
});

// Meten starten en stoppen met de property active van vl-map-measure-action.
document.querySelector('#measure-start-button').addEventListener('click', () => {
    getAction('measure').active = true;
});
document.querySelector('#measure-stop-button').addEventListener('click', () => {
    getAction('measure').active = false;
});

// Een toggle-knop zet zijn eigen on om voor de click deze listener bereikt; de actie volgt de knop.
actionNames.forEach((name) => {
    getToggleButton(name).addEventListener('click', () => {
        getAction(name).active = getToggleButton(name).on;
    });
});

// Omgekeerd: verandert de actieve actie op de kaart, dan volgen de toggle-knoppen.
map.addEventListener('vl-active-action-changed', ({ detail: { previous, current } }) => {
    actionNames.forEach((name) => {
        if (previous === getAction(name)) {
            getToggleButton(name).on = false;
        } else if (current === getAction(name)) {
            getToggleButton(name).on = true;
        }
    });
});

// Wordt een kaartlaag onzichtbaar, dan schakelen de knoppen van haar acties uit.
map.addEventListener('vl-layer-visible-changed', ({ detail: { layer, visible } }) => {
    for (const layerAction of layer.getElementsByClassName('action')) {
        actionNames.forEach((name) => {
            if (layerAction === getAction(name)) {
                getToggleButton(name).disabled = !visible;
            }
        });
    }
});

// hasInvalidGeometries() meldt of een kaartlaag een ongeldige geometrie bevat; de toaster toont het resultaat.
document.querySelector('#check-invalid-button').addEventListener('click', () => {
    const hasInvalidGeometries = map.hasInvalidGeometries();
    document.querySelector('#toaster-invalid').showAlert({
        icon: hasInvalidGeometries ? 'alert-circle' : 'check-circle',
        type: hasInvalidGeometries ? 'error' : 'success',
        message: `Deze kaart heeft ${hasInvalidGeometries ? '' : 'GEEN'} ongeldige geometrieën.`,
        closable: true,
    });
});

